{
  "tasks": [
    {
      "task_id": "T01",
      "title": "各城市岗位数量分布",
      "business_question": "不同城市的招聘岗位数量分别是多少？",
      "priority": "P0",
      "priority_reason": "核心需求为探索主要分布，城市是招聘数据中最基础的地域维度，统计各城市岗位数是回答“分布”问题的首要步骤。删除此任务将无法了解地域层面的差异。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "job_count"
              }
            ],
            "dimensions": [
              "field_0001"
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "sort",
          "params": {
            "field": "job_count",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T02",
      "title": "各学历要求的岗位数量分布",
      "business_question": "不同学历要求的招聘岗位数量分别是多少？",
      "priority": "P0",
      "priority_reason": "核心需求为探索主要分布和差异，学历是招聘数据中的关键属性维度。分析学历分布有助于理解人才要求的主要构成，是探索性分析中不可或缺的部分。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "job_count"
              }
            ],
            "dimensions": [
              "field_0005"
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "sort",
          "params": {
            "field": "job_count",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T03",
      "title": "薪资水平概况（数值字段）",
      "business_question": "基于‘薪资元’字段的平均薪资是多少？",
      "priority": "P1",
      "priority_reason": "虽然‘薪资区间’是文本字段无法直接聚合，但存在‘薪资元’整数字段（尽管有缺失值）。计算其均值可提供薪资水平的一个量化参考，辅助理解分布情况。若该字段业务含义不明确或质量差，此任务价值降低，故定为P1。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "avg_salary_numeric"
              }
            ]
          }
        }
      ]
    }
  ]
}
